class Widget {
public:
  // This version can only be called on lvalue Widgets
  void doWork() &;

  // This version can only be called on rvalue Widgets
  void doWork() &&;
};

Widget makeWidget(); // Factory function that returns an rvalue

Widget w; // w is an lvalue

w.doWork();             // Calls Widget::doWork() &

makeWidget().doWork();  // Calls Widget::doWork() &&
